from dataclasses import dataclass, field
from typing import Optional

from shop.domain.ports import OrderRepository


@dataclass
class Order:
    id: str
    total_cents: int
    repo: Optional[OrderRepository] = field(default=None, compare=False, repr=False)

    def save(self) -> None:
        if self.repo is None:
            raise ValueError("Order has no repository attached")
        self.repo.save(self)

